   */
  legacySealFallback?: boolean;
  crypto?: Crypto;
  /** Default is Crypto.randomUUID */
  generateId?: () => string;
}

/**
 * Create a session manager for the current request.
 *
 * Starts a session if the request does not carry one, persisting it so its id
 * is stable across requests. Use {@link getSession} to read a session without
 * starting one.
 */
export async function useSession<T extends SessionData = SessionData>(
  event: HTTPEvent,
  config: SessionConfig,
): Promise<SessionManager<T>> {
  // Create a synced wrapper around the session
  const sessionName = config.name || DEFAULT_SESSION_NAME;
  // Force init: persist a session created during this request so its id is stable
  const session = await getSession(event, config);
  if (session[kSessionNew]) {
    await updateSession(event, config);
  }
  const sessionManager = {
    get id() {
      const context = getEventContext<H3EventContext>(event);
      return context?.sessions?.[sessionName]?.id;
    },
    get data() {
      const context = getEventContext<H3EventContext>(event);
      return (context.sessions?.[sessionName]?.data || new EmptyObject()) as T;
    },
    update: async (update: SessionUpdate<T>) => {
      await updateSession<T>(event, config, update);
      return sessionManager;
    },
    clear: () => {
      clearSession(event, config);
      return Promise.resolve(sessionManager);
    },
  };
  return sessionManager;
}

/**
 * Get the session for the current request.
 *
 * A request without a session gets a new one initialized in memory only — no
 * `Set-Cookie` is issued until something is stored with {@link updateSession},
 * so reading the session (an auth check, for example) does not start one for
 * anonymous visitors. Its `id` is therefore only stable across requests once
 * the session has been written; use {@link useSession} to start one eagerly.
 */
export async function getSession<T extends SessionData = SessionData>(
  event: HTTPEvent,
  config: SessionConfig,
): Promise<Session<T>> {
  const sessionName = config.name || DEFAULT_SESSION_NAME;

  const context = getEventContext<H3EventContext>(event);

  // Return existing session if available
  if (!context.sessions) {
    context.sessions = new EmptyObject();
  }
  // Wait for existing session to load
  const existingSession = context.sessions![sessionName] as Session<T>;
  if (existingSession) {
    return existingSession[kGetSession] || existingSession;
  }

  // Prepare an empty session object and store in context
  const session: Session<T> = {
    id: "",
    createdAt: 0,
    data: new EmptyObject(),
  };
  context.sessions![sessionName] = session;

  // Try to load session
  let sealedSession: string | undefined;
  // Try header first
  if (config.sessionHeader !== false) {
    const headerName =
      typeof config.sessionHeader === "string"
        ? config.sessionHeader.toLowerCase()
        : `x-${sessionName.toLowerCase()}-session`;
    const headerValue = event.req.headers.get(headerName);
    if (typeof headerValue === "string") {
      sealedSession = headerValue;
    }
  }
  // Fallback to cookies
  let sessionFromCookie = false;
  if (!sealedSession) {
    sealedSession = getChunkedCookie(event, sessionName);
    sessionFromCookie = true;
  }
  if (sealedSession) {
    // Unseal session data from cookie
    const promise = unsealSession(event, config, sealedSession)
      .catch(() => {})
      .then(async (unsealed) => {
        const legacySeal = unsealed && (unsealed as any)[kLegacySeal];
        if (legacySeal) {
          delete (unsealed as any)[kLegacySeal];
        }
        const extraSeal = unsealed && (unsealed as any)[kExtraSeal];
        if (extraSeal) {
          delete (unsealed as any)[kExtraSeal];
        }
        // `JSON.parse` yields plain objects; keep live data prototype-free so a
        // `__proto__` key in a later `updateSession` cannot swap its prototype.
        if (unsealed?.data) {
          unsealed.data = Object.assign(new EmptyObject(), unsealed.data);
        }
        Object.assign(session, unsealed);
        delete context.sessions![sessionName][kGetSession];
        // Proactively reseal legacy cookies with the current seal options, and
        // cookies opened with a previous password (`extraUnsealPasswords`) with
        // `password`. Also reseal under idleTimeout to slide the window (see
        // `shouldSlide`). A session that failed to unseal has no id and is
        // replaced below, so resealing it here is wasted work.
        if (
          session.id &&
          sessionFromCookie &&
          (legacySeal || extraSeal || shouldSlide(session, config))
        ) {
          await updateSession(event, config);
        }
        return session as Session<T>;
      });
    context.sessions![sessionName][kGetSession] = promise;
    await promise;
  }

  // New session: initialize in memory only. It is persisted by the first
  // `updateSession` (or by `useSession`, which force-inits).
  if (!session.id) {
    session.id = config.generateId?.() ?? (config.crypto || crypto).randomUUID();
    session.createdAt = Date.now();
    session[kSessionNew] = true;
  }

  return session;
}

type SessionUpdate<T extends SessionData = SessionData> =
  | Partial<SessionData<T>>
  | ((oldData: SessionData<T>) => Partial<SessionData<T>> | undefined);

/**
 * Update the session data for the current request.
 */
export async function updateSession<T extends SessionData = SessionData>(
  event: HTTPEvent,
  config: SessionConfig,
  update?: SessionUpdate<T>,
): Promise<Session<T>> {
  const sessionName = config.name || DEFAULT_SESSION_NAME;

  // Access current session
  const context = getEventContext<H3EventContext>(event);
  const session: Session<T> =
    (context.sessions?.[sessionName] as Session<T>) || (await getSession<T>(event, config));

  // Update session data if provided
  if (typeof update === "function") {
    update = update(session.data);
  }
  if (update) {
    Object.assign(session.data, update);
  }

  // Persisted (or persistence is disabled by config): no longer a fresh session
  // awaiting its first write.
  delete session[kSessionNew];

  // Seal and store in cookie
  if (config.cookie !== false && (event as H3Event).res) {
    const sealed = await sealSession(event, config);
    setChunkedCookie(event as H3Event, sessionName, sealed, {
      ...DEFAULT_SESSION_COOKIE,
      expires: sessionExpires(session, config),
      ...config.cookie,
    });
    stageSessionErrCookies(event as H3Event, sessionName);
  }

  return session;
}

/**
 * Encrypt and sign the session data for the current request.
 */
export async function sealSession<T extends SessionData = SessionData>(
  event: HTTPEvent,
  config: SessionConfig,
): Promise<string> {
  const sessionName = config.name || DEFAULT_SESSION_NAME;

  // Access current session
  const context = getEventContext<H3EventContext>(event);
  const session: Session<T> =
    (context.sessions?.[sessionName] as Session<T>) || (await getSession<T>(event, config));

  if (config.idleTimeout) {
    // The idle window is measured from the last reseal rather than from
    // createdAt. Only stamped when enabled, so the default sealed payload is
    // unchanged.
    session.lastSeenAt = Date.now();
  }

  const sealed = await seal(session, config.password, {
    ...sealDefaults,
    ttl: (config.maxAge || config.idleTimeout || 0) * 1000,
    ...config.seal,
  });

  return sealed;
}

/**
 * Decrypt and verify the session data for the current request.
 */
export async function unsealSession(
  _event: HTTPEvent,
  config: SessionConfig,
  sealed: string,
): Promise<Partial<Session>> {
  const sealOptions = {
    ...sealDefaults,
    ttl: (config.maxAge || config.idleTimeout || 0) * 1000,
    ...config.seal,
  };
  // `password` first, then the previous passwords in order. Duplicates are
  // dropped, so a password copied into the list is not tried twice.
  const passwords = [...new Set([config.password, ...(config.extraUnsealPasswords ?? [])])];
  let opened: Awaited<ReturnType<typeof unsealWithPasswords>>;
  try {
    opened = await unsealWithPasswords(sealed, passwords, sealOptions);
  } catch (error) {
    // TODO: Remove this fallback (and `legacySealFallback`) in v3. Removing it
    // in a v2 release would invalidate existing sessions sealed with 1 iteration.
    // Sessions sealed before the default PBKDF2 iterations were raised from 1
    // to 8192 fail HMAC verification; retry with the legacy count so existing
    // sessions survive the upgrade (getSession reseals them with the current
    // options). The legacy pass runs only after every password failed with the
    // current count, so a cookie costs at most one extra pass.
    if (
      config.legacySealFallback === false ||
      sealOptions.integrity.iterations === 1 ||
      !(error instanceof Error) ||
      error.message !== "Bad hmac value"
    ) {
      throw error;
    }
    opened = await unsealWithPasswords(sealed, passwords, {
      ...sealOptions,
      encryption: { ...sealOptions.encryption, iterations: 1 },
      integrity: { ...sealOptions.integrity, iterations: 1 },
    });
    (opened.unsealed as any)[kLegacySeal] = true;
  }
  const unsealed = opened.unsealed;
  if (opened.password !== config.password) {
    // Opened with a previous password: getSession reseals it with `password`
    (unsealed as any)[kExtraSeal] = true;
  }
  // Absolute lifetime, counted from when the session was created
  if (config.maxAge) {
    const age = Date.now() - (unsealed.createdAt || Number.NEGATIVE_INFINITY);
    if (age > config.maxAge * 1000) {
      throw new Error("Session expired!");
    }
  }
  // Idle window, counted from the last reseal. Sessions sealed before
  // idleTimeout was configured, and sessions read from the session header (which
  // are never resealed), fall back to createdAt
  if (config.idleTimeout) {
    const idle =
      Date.now() - (unsealed.lastSeenAt || unsealed.createdAt || Number.NEGATIVE_INFINITY);
    if (idle > config.idleTimeout * 1000) {
      throw new Error("Session expired!");
    }
  }
  return unsealed;
}

/**
 * Clear the session data for the current request.
 */
export function clearSession(event: HTTPEvent, config: Partial<SessionConfig>): Promise<void> {
  const context = getEventContext<H3EventContext>(event);
  const sessionName = config.name || DEFAULT_SESSION_NAME;
  if (context.sessions?.[sessionName]) {
    delete context.sessions![sessionName];
  }
  if ((event as H3Event).res && config.cookie !== false) {
    deleteChunkedCookie(event as H3Event, sessionName, {
      ...DEFAULT_SESSION_COOKIE,
      ...config.cookie,
    });
    stageSessionErrCookies(event as H3Event, sessionName);
  }
  return Promise.resolve();
}

/**
 * Fraction of the idle window that has to be used up before `getSession`
 * reseals to slide it. See {@link shouldSlide}.
 */
const SLIDE_THRESHOLD = 0.5;

/**
 * Whether reading the session should also reseal it to move the idle window
 * forward.
 *
 * Sliding the window means writing `lastSeenAt` back into the cookie, and that
 * seal is by far the most expensive thing a session does. Doing it on every
 * request also wastes it twice over on a request that writes the session: the
 * handler's `update()` reseals with the same fresh `lastSeenAt`, and
 * `setCookie`'s dedupe drops the first `Set-Cookie` anyway.
 *
 * So reseal only once the window is more than half used. Any `updateSession`
 * (from a handler write, or from the reseal itself) restamps `lastSeenAt`, so
 * writes keep sliding the window for free and a request that both reads and
 * writes almost never seals twice.
 *
 * The trade-off is granularity, in the safe direction: `lastSeenAt` can trail
 * the last request by up to half the window, so an idle session is signed out
 * somewhere between `idleTimeout / 2` and `idleTimeout` after the last request,
 * never later.
 */
function shouldSlide(session: Session<any>, config: SessionConfig): boolean {
  if (!config.idleTimeout) {
    return false;
  }
  // Sessions sealed before `idleTimeout` was configured have no `lastSeenAt`
  const lastSeenAt = session.lastSeenAt || session.createdAt || 0;
  return Date.now() - lastSeenAt > config.idleTimeout * 1000 * SLIDE_THRESHOLD;
}

/**
 * Mirror this session's `Set-Cookie` headers into `event.res.errHeaders`.
 *
 * Error responses only receive headers explicitly staged as `errHeaders`, so
 * without this a request that throws drops the session cookie entirely: a
 * session created during that request is lost, and under `idleTimeout` the idle
 * window fails to slide even though the user was active.
 *
 * Re-staged from scratch on every write so the latest state wins — in
 * particular, a `clearSession` after a reseal must not leave the stale reseal
 * cookie behind to resurrect the session on an error response.
 */
function stageSessionErrCookies(event: H3Event, sessionName: string): void {
  // Chunks are stored as `{name}.{n}` by `setChunkedCookie`
  const isSessionCookie = (cookie: string) =>
    cookie.startsWith(`${sessionName}=`) || cookie.startsWith(`${sessionName}.`);

  const errHeaders = event.res.errHeaders;
  const staged = [
    ...errHeaders.getSetCookie().filter((cookie) => !isSessionCookie(cookie)),
    ...event.res.headers.getSetCookie().filter((cookie) => isSessionCookie(cookie)),
  ];
  errHeaders.delete("set-cookie");
  for (const cookie of staged) {
    errHeaders.append("set-cookie", cookie);
  }
}

/**
 * Cookie expiry: whichever of the absolute lifetime and the idle window runs out
 * first, or none if neither is configured.
 */
function sessionExpires(session: Session<any>, config: SessionConfig): Date | undefined {
  const times: number[] = [];
  if (config.maxAge) {
    times.push(session.createdAt + config.maxAge * 1000);
  }
  if (config.idleTimeout) {
    times.push((session.lastSeenAt || session.createdAt) + config.idleTimeout * 1000);
  }
  return times.length > 0 ? new Date(Math.min(...times)) : undefined;
}

import type { SessionConfig } from "../src/utils/session.ts";
import { beforeEach, describe, vi } from "vitest";
import { useSession, getSession, readBody } from "../src/index.ts";
import { seal, unseal, defaults as sealDefaults } from "../src/utils/internal/iron-crypto.ts";
import { describeMatrix } from "./_setup.ts";

// Passwords must be at least 32 characters (iron-crypto.ts). The PRD's A/B/C are labels.
const A = "a-secret-".repeat(5);
const B = "b-secret-".repeat(5);
const C = "c-secret-".repeat(5);
const X = "x-secret-".repeat(5);
const SHORT = "too-short";

const SESSION_NAME = "h3-sdd";
const PAYLOAD = { id: "sdd-old", createdAt: Date.now(), data: { user: "alice" } };

const legacyOptions = {
  ...sealDefaults,
  encryption: { ...sealDefaults.encryption, iterations: 1 },
  integrity: { ...sealDefaults.integrity, iterations: 1 },
};

const cookieValue = (res: Response) => {
  const setCookie = res.headers.getSetCookie().find((c) => c.startsWith(`${SESSION_NAME}=`));
  return setCookie ? decodeURIComponent(setCookie.match(/=([^;]+)/)![1]) : undefined;
};

describeMatrix("sdd: extraUnsealPasswords", (t, { it, expect }) => {
  const config: SessionConfig = {
    name: SESSION_NAME,
    password: B,
    extraUnsealPasswords: [A],
    generateId: () => "sdd-new",
  };

  beforeEach(() => {
    t.app.get("/read", async (event) => {
      const session = await getSession(event, config);
      return { id: session.id, data: session.data };
    });
    t.app.post("/write", async (event) => {
      const session = await useSession(event, config);
      await session.update((await readBody(event)) as any);
      return { id: session.id, data: session.data };
    });
  });

  // RF-01
  it("opens a session sealed with a previous password", async () => {
    const sealed = await seal(PAYLOAD, A, sealDefaults);

    const res = await t.fetch("/read", { headers: { Cookie: `${SESSION_NAME}=${sealed}` } });
    expect(await res.json()).toMatchObject({ id: "sdd-old", data: { user: "alice" } });
  });

  // RF-02
  it("seals a new session with the current password only", async () => {
    const res = await t.fetch("/write", { method: "POST", body: JSON.stringify({ n: 1 }) });
    const sealed = cookieValue(res)!;

    expect(sealed).toBeDefined();
    expect(await unseal(sealed, B, sealDefaults)).toMatchObject({ data: { n: 1 } });
    await expect(unseal(sealed, A, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  // RF-02
  it("reseals an updated session with the current password only", async () => {
    const sealed = await seal(PAYLOAD, A, sealDefaults);

    const res = await t.fetch("/write", {
      method: "POST",
      headers: { Cookie: `${SESSION_NAME}=${sealed}` },
      body: JSON.stringify({ n: 2 }),
    });
    const resealed = cookieValue(res)!;

    expect(await unseal(resealed, B, sealDefaults)).toMatchObject({
      id: "sdd-old",
      data: { user: "alice", n: 2 },
    });
    await expect(unseal(resealed, A, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  // RF-03
  it("reseals a cookie opened with a previous password using the current password", async () => {
    const sealed = await seal(PAYLOAD, A, sealDefaults);

    const res = await t.fetch("/read", { headers: { Cookie: `${SESSION_NAME}=${sealed}` } });
    const resealed = cookieValue(res);

    expect(resealed).toBeDefined();
    expect(await unseal(resealed!, B, sealDefaults)).toMatchObject({
      id: "sdd-old",
      data: { user: "alice" },
    });
    await expect(unseal(resealed!, A, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  // RF-03: the migrated cookie must not leak the internal marker into the session
  it("does not expose the extra-seal marker on the returned session", async () => {
    const marker = Symbol.for("h3.internal.session.extra-seal");
    let symbols: symbol[] = [];
    t.app.get("/symbols", async (event) => {
      const session = await getSession(event, config);
      symbols = Object.getOwnPropertySymbols(session);
      return { id: session.id };
    });
    const sealed = await seal(PAYLOAD, A, sealDefaults);

    await t.fetch("/symbols", { headers: { Cookie: `${SESSION_NAME}=${sealed}` } });
    expect(symbols).not.toContain(marker);
  });

  // RF-04
  it("returns an empty session for a password that is not in the configuration", async () => {
    const sealed = await seal(PAYLOAD, C, sealDefaults);

    const res = await t.fetch("/read", { headers: { Cookie: `${SESSION_NAME}=${sealed}` } });
    const body = await res.json();
    expect(res.status).toBe(200);
    expect(body.data).toEqual({});
    expect(body.id).not.toBe("sdd-old");
  });

  // RF-05
  it("keeps the current behavior when extraUnsealPasswords is empty", async () => {
    t.app.get("/empty-list", async (event) => {
      const session = await getSession(event, { ...config, extraUnsealPasswords: [] });
      return { id: session.id, data: session.data };
    });
    const withB = await seal(PAYLOAD, B, sealDefaults);
    const withA = await seal(PAYLOAD, A, sealDefaults);

    const ok = await t.fetch("/empty-list", { headers: { Cookie: `${SESSION_NAME}=${withB}` } });
    expect(ok.headers.getSetCookie()).toHaveLength(0);
    expect(await ok.json()).toMatchObject({ id: "sdd-old", data: { user: "alice" } });

    const rejected = await t.fetch("/empty-list", {
      headers: { Cookie: `${SESSION_NAME}=${withA}` },
    });
    expect((await rejected.json()).data).toEqual({});
  });

  // D-01 / D-02: the list is tried in order
  it("opens a session sealed with the second password in the list", async () => {
    t.app.get("/ordered", async (event) => {
      const session = await getSession(event, {
        ...config,
        extraUnsealPasswords: [X, A],
      });
      return { id: session.id, data: session.data };
    });
    const sealed = await seal(PAYLOAD, A, sealDefaults);

    const res = await t.fetch("/ordered", { headers: { Cookie: `${SESSION_NAME}=${sealed}` } });
    expect(await res.json()).toMatchObject({ id: "sdd-old", data: { user: "alice" } });
  });

  // D-02: legacy (1 iteration) cookie under a previous password
  it("unseals and reseals a legacy cookie sealed with a previous password", async () => {
    const sealed = await seal(PAYLOAD, A, legacyOptions);

    const res = await t.fetch("/read", { headers: { Cookie: `${SESSION_NAME}=${sealed}` } });
    expect(await res.json()).toMatchObject({ id: "sdd-old", data: { user: "alice" } });

    const resealed = cookieValue(res)!;
    expect(await unseal(resealed, B, sealDefaults)).toMatchObject({
      id: "sdd-old",
      data: { user: "alice" },
    });
  });

  // D-02: the legacy fallback can be disabled, and then the legacy cookie is rejected
  it("rejects a legacy cookie under a previous password with legacySealFallback: false", async () => {
    t.app.get("/strict-legacy", async (event) => {
      const session = await getSession(event, { ...config, legacySealFallback: false });
      return { id: session.id, data: session.data };
    });
    const sealed = await seal(PAYLOAD, A, legacyOptions);

    const res = await t.fetch("/strict-legacy", {
      headers: { Cookie: `${SESSION_NAME}=${sealed}` },
    });
    const body = await res.json();
    expect(body.id).not.toBe("sdd-old");
    expect(body.data).toEqual({});
  });

  // D-04: a password repeated in the list does not add derivations
  it("does not repeat a password that is listed twice", async () => {
    t.app.get("/dedup-plain", async (event) => {
      const session = await getSession(event, { ...config, extraUnsealPasswords: [] });
      return { id: session.id };
    });
    t.app.get("/dedup-twice", async (event) => {
      const session = await getSession(event, { ...config, extraUnsealPasswords: [B, B] });
      return { id: session.id };
    });
    const sealed = await seal(PAYLOAD, C, sealDefaults);
    const headers = { Cookie: `${SESSION_NAME}=${sealed}` };

    const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
    try {
      deriveBits.mockClear();
      await t.fetch("/dedup-plain", { headers });
      const plain = deriveBits.mock.calls.length;

      deriveBits.mockClear();
      await t.fetch("/dedup-twice", { headers });
      expect(deriveBits.mock.calls.length).toBe(plain);
    } finally {
      deriveBits.mockRestore();
    }
  });

  // D-05: an error that does not depend on the password stops the loop at once
  it("does not try other passwords when the seal is expired", async () => {
    const expired = await seal(PAYLOAD, A, { ...sealDefaults, ttl: -120_000 });

    const res = await t.fetch("/read", { headers: { Cookie: `${SESSION_NAME}=${expired}` } });
    const body = await res.json();
    expect(body.id).not.toBe("sdd-old");
    expect(body.data).toEqual({});
  });

  // R-02: a short extra password fails the same way as a short password, and the
  // failure becomes an empty session. This fixes the current rule.
  it("returns an empty session when an extra password is shorter than 32 characters", async () => {
    t.app.get("/short", async (event) => {
      const session = await getSession(event, { ...config, extraUnsealPasswords: [SHORT] });
      return { id: session.id, data: session.data };
    });
    const sealed = await seal(PAYLOAD, A, sealDefaults);

    const res = await t.fetch("/short", { headers: { Cookie: `${SESSION_NAME}=${sealed}` } });
    expect(res.status).toBe(200);
    expect((await res.json()).data).toEqual({});
  });

  // D-08: a session read from the header is never resealed
  it("does not reseal a session read from the session header", async () => {
    const sealed = await seal(PAYLOAD, A, sealDefaults);

    const res = await t.fetch("/read", { headers: { "x-h3-sdd-session": sealed } });
    expect(await res.json()).toMatchObject({ id: "sdd-old", data: { user: "alice" } });
    expect(res.headers.getSetCookie()).toHaveLength(0);
  });
});
